argv:
$ErrorActionPreference='SilentlyContinue'
$repo='E:\work\video2-r25-local'
$procs=@()
Get-CimInstance Win32_Process -Filter "Name='node.exe'" | Where-Object {
  $_.CommandLine -like '*video2-r25-local*' -or $_.CommandLine -like '*tournament-r25.test.js*' -or $_.CommandLine -like '*r25-candidate4-checkpoint.test.js*'
} | ForEach-Object { $procs += [pscustomobject]@{pid=$_.ProcessId;cmd=$_.CommandLine} }
$status=@(git -C $repo status --short 2>$null)
[pscustomobject]@{
 head=(git -C $repo rev-parse HEAD 2>$null | Select-Object -First 1)
 status=$status
 processes=$procs
 artifactsExists=(Test-Path (Join-Path $repo '.artifacts'))
} | ConvertTo-Json -Depth 4 -Compress
